if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_6136f43e35880d3d64991bd05fd63d6d' and entity_id='inv_f10a63e814894568fd3da0d92ad330d8' and md5(to_jsonb(t)::text)='3cba150e8fcb54b5d26effb2c84e4a42')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_f10a63e814894568fd3da0d92ad330d8';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_558a95cebcb036e3$"Objeto · Precio base · Peso · Unidades por paquete · Peso por unidad (lb) · Precio por unidad (pc)\nFlecha · 1 po · 1 lb · 20 · 0.05 · 5\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_558a95cebcb036e3$::jsonb,true),'{rules,definition,description}',$text_1086a208ec8f4634$[{"id":"official-table","rows":[["Flecha","1 po","1 lb","20","0.05","5"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_1086a208ec8f4634$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_6136f43e35880d3d64991bd05fd63d6d' and entity_id='inv_f10a63e814894568fd3da0d92ad330d8';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_6e02527e3880499aaa59ea5182ca2c7e' and entity_id='inv_0a4f82ec5759406eaf8d317fbcc997fc' and md5(to_jsonb(t)::text)='eaa264bec3d21d13228d101a11547f3c')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_0a4f82ec5759406eaf8d317fbcc997fc';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_b3e6b109a5d3d596$"Objeto · Precio base · Peso\nAceite (frasco) · 1 pp · 1 lb\n\nAceite. El aceite suele venir en frascos de arcilla con capacidad para 0,5 l. Como acción, puedes esparcir el aceite de este frasco sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el frasco se rompa con el impacto. En ambos casos, haz un ataque a distancia contra la criatura o el objeto y trata el aceite como un arma improvisada: si tienes éxito, el objetivo quedará cubierto de aceite. Si el objetivo sufre daño de fuego antes de que el aceite se seque (lo que ocurre tras 1 minuto), recibirá 5 de daño de fuego adicional debido al aceite ardiendo. También puedes derramar un frasco de aceite por el suelo, que cubrirá una zona de 1,5 m de lado, siempre y cuando la superficie esté nivelada. Si se prende, el aceite arderá durante 2 asaltos y causará 5 de daño de fuego a cualquier criatura que entre en la zona o acabe su turno en ella. Una criatura solo puede sufrir este daño una vez por turno.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_b3e6b109a5d3d596$::jsonb,true),'{features}',$text_e92c7a74615a59ed$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Aceite. El aceite suele venir en frascos de arcilla con capacidad para 0,5 l. Como acción, puedes esparcir el aceite de este frasco sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el frasco se rompa con el impacto. En ambos casos, haz un ataque a distancia contra la criatura o el objeto y trata el aceite como un arma improvisada: si tienes éxito, el objetivo quedará cubierto de aceite. Si el objetivo sufre daño de fuego antes de que el aceite se seque (lo que ocurre tras 1 minuto), recibirá 5 de daño de fuego adicional debido al aceite ardiendo. También puedes derramar un frasco de aceite por el suelo, que cubrirá una zona de 1,5 m de lado, siempre y cuando la superficie esté nivelada. Si se prende, el aceite arderá durante 2 asaltos y causará 5 de daño de fuego a cualquier criatura que entre en la zona o acabe su turno en ella. Una criatura solo puede sufrir este daño una vez por turno.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_e92c7a74615a59ed$::jsonb,true),'{rules,definition,description}',$text_203958f9770774af$[{"id":"official-table","rows":[["Aceite (frasco)","1 pp","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Aceite. El aceite suele venir en frascos de arcilla con capacidad para 0,5 l. Como acción, puedes esparcir el aceite de este frasco sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el frasco se rompa con el impacto. En ambos casos, haz un ataque a distancia contra la criatura o el objeto y trata el aceite como un arma improvisada: si tienes éxito, el objetivo quedará cubierto de aceite. Si el objetivo sufre daño de fuego antes de que el aceite se seque (lo que ocurre tras 1 minuto), recibirá 5 de daño de fuego adicional debido al aceite ardiendo. También puedes derramar un frasco de aceite por el suelo, que cubrirá una zona de 1,5 m de lado, siempre y cuando la superficie esté nivelada. Si se prende, el aceite arderá durante 2 asaltos y causará 5 de daño de fuego a cualquier criatura que entre en la zona o acabe su turno en ella. Una criatura solo puede sufrir este daño una vez por turno.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_203958f9770774af$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_6e02527e3880499aaa59ea5182ca2c7e' and entity_id='inv_0a4f82ec5759406eaf8d317fbcc997fc';
