eb8438$::jsonb,true),'{rules,definition,description}',$text_3add5ea142dca2e1$[{"id":"official-table","rows":[["Útiles de escalada","25 po","12 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Útiles de escalada. Entre estos útiles se incluyen pitones especiales, puntas para las botas y un arnés. Puedes usar una acción para anclarte mediante estos útiles. Cuando lo hayas hecho, no podrás caer más de 7,5 m desde el punto en el que te ancles y no podrás subir más de 7,5 m de ese punto sin desanclarte.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_3add5ea142dca2e1$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_6e02527e3880499aaa59ea5182ca2c7e' and entity_id='inv_26edd2837738414aa2f6cb80036f3596';
