if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_4e1487bfd21bae3227a8feaadf7297ed' and md5(to_jsonb(t)::text)='eccf96b69219f1f6c105f14d7e7f567a')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_4e1487bfd21bae3227a8feaadf7297ed';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_c15551ec8d633855$"Objeto · Precio base · Peso\nYesquero · 5 pp · 1 lb\n\nYesquero. Esta pequeña caja contiene un pedernal, un chispero y yescas (normalmente, tela seca untada en aceite) que se utilizan para encender un fuego. Utilizar el yesquero para prender una antorcha (o cualquier otra cosa altamente inflamable) requiere una acción. Encender cualquier otro tipo de fuego lleva 1 minuto.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_c15551ec8d633855$::jsonb,true),'{features}',$text_bd65b4d01e3d68ec$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Yesquero. Esta pequeña caja contiene un pedernal, un chispero y yescas (normalmente, tela seca untada en aceite) que se utilizan para encender un fuego. Utilizar el yesquero para prender una antorcha (o cualquier otra cosa altamente inflamable) requiere una acción. Encender cualquier otro tipo de fuego lleva 1 minuto.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_bd65b4d01e3d68ec$::jsonb,true),'{rules,definition,description}',$text_814298e44215c03b$[{"id":"official-table","rows":[["Yesquero","5 pp","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Yesquero. Esta pequeña caja contiene un pedernal, un chispero y yescas (normalmente, tela seca untada en aceite) que se utilizan para encender un fuego. Utilizar el yesquero para prender una antorcha (o cualquier otra cosa altamente inflamable) requiere una acción. Encender cualquier otro tipo de fuego lleva 1 minuto.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_814298e44215c03b$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_4e1487bfd21bae3227a8feaadf7297ed';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_5c88a2f8ee8bc23f1d67a8e1440b86ec' and md5(to_jsonb(t)::text)='85590a3e1a082f64059b9cd19aed9deb')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_5c88a2f8ee8bc23f1d67a8e1440b86ec';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_fb0110dc01b844c7$"Objeto · Precio base · Peso\nMochila · 2 po · 5 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_fb0110dc01b844c7$::jsonb,true),'{rules,definition,description}',$text_467c0a803342b9d2$[{"id":"official-table","rows":[["Mochila","2 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_467c0a803342b9d2$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_5c88a2f8ee8bc23f1d67a8e1440b86ec';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_89ce12a51c68147ff69ed153c86ea4cb' and md5(to_jsonb(t)::text)='4b433f54c2bbf1b3973661b963a547d8')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_89ce12a51c68147ff69ed153c86ea4cb';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_569cb37696c7d3eb$"Objeto · Precio base · Peso\nHerramientas de cartógrafo · 15 po · 6 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_569cb37696c7d3eb$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_08ae83fa509ef72d$[{"id":"official-table","rows":[["Herramientas de cartógrafo","15 po","6 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_08ae83fa509ef72d$::jsonb,true),'{catalog,revision}',$text_4b227777d4dd1fc6$4$text_4b227777d4dd1fc6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_89ce12a51c68147ff69ed153c86ea4cb';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_98db2f4b7832d87ef8ebc0bd96d398c5' and md5(to_jsonb(t)::text)='2936d60e75c49a5534c1304aacda6b9c')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_98db2f4b7832d87ef8ebc0bd96d398c5';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_216b4d63fe402084$"Objeto · Precio base · Peso\nPitón · 5 pc · 0.25 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_216b4d63fe402084$::jsonb,true),'{rules,definition,description}',$text_70ac9ee2fca680b8$[{"id":"official-table","rows":[["Pitón","5 pc","0.25 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_70ac9ee2fca680b8$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_98db2f4b7832d87ef8ebc0bd96d398c5';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_a3f66bf2477fa1d5316cd5f74a9c1219' and md5(to_jsonb(t)::text)='3cc02c260687e32aba1ca020a00132af')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_a3f66bf2477fa1d5316cd5f74a9c1219';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(payload,'{features}',$text_2665a32b1b3ad0b3$[{"id":"intelligence-bonus","kind":"passive","name":"Inteligencia +1","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras estés sintonizado con Sombra del Segador y el objeto esté en contacto con tu cuerpo, tu puntuación de Inteligencia aumenta en 1. Marca de la Cercanía tiene un uso y recupera el uso gastado al amanecer. Los demás poderes, requisitos y contrapartidas conservan sus reglas descritas.\n\nDuración: Mientras se cumplan equipo y sintonización..","showInActions":false},{"id":"veil-of-penumbra","kind":"other","name":"Velo de Penumbra","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Velo de Penumbra\n\nMientras estés vinculado al objeto, la luz en un radio de 3 metros (10 pies) se atenúa ligeramente. La luz brillante pasa a ser luz tenue, y la luz tenue pasa a ser oscuridad no mágica (las criaturas con visión en la oscuridad ven esta área como luz tenue). Las criaturas que dependen de la vista tienen desventaja en las tiradas de Percepción para detectar al portador si permanece inmóvil.\n\nLuz brillante pasa a tenue y luz tenue a oscuridad no mágica a 10 pies; conservar la interacción con visión en la oscuridad descrita por el objeto.\n\nDuración: Mientras se cumplan equipo y sintonización..\n\nAlcance: Radio de 10 pies (3 m).","showInActions":false},{"id":"nearness-mark","kind":"other","name":"Marca de la Cercanía","uses":null,"order":2,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"2d6"}],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Marca de la Cercanía (1/día)\n\nComo acción adicional, puedes marcar a una criatura que veas a 9 metros (30 pies). Durante 1 minuto:\n\nLa primera vez que el objetivo caiga por debajo de la mitad de sus puntos de golpe, recibe 2d6 de daño necrótico adicional.\n\nEl objetivo no puede beneficiarse de puntos de golpe temporales durante este efecto.\n\nEste efecto termina antes si pierdes la concentración (como si concentraras un conjuro, CD 10 o la mitad del daño recibido, lo que sea mayor).\n\nMientras estés sintonizado con Sombra del Segador y el objeto esté en contacto con tu cuerpo, tu puntuación de Inteligencia aumenta en 1. Marca de la Cercanía tiene un uso y recupera el uso gastado al amanecer. Los demás poderes, requisitos y contrapartidas conservan sus reglas descritas.\n\nEl objetivo no puede beneficiarse de PG temporales mientras dure la marca; termina al perder la concentración o al cumplirse 1 minuto.\n\nDuración: Hasta 1 minuto.\n\nAlcance: 30 pies (9 m).\n\nConcentración: sí.\n\nCoste: 1 Marca de la Cercanía.","showInActions":false},{"id":"lingering-presence","kind":"other","name":"Presencia Persistente","uses":null,"order":3,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Presencia Persistente\n\nCuando una criatura muere a menos de 4,5 metros (15 pies) de ti, obtienes ventaja en tu siguiente tirada de ataque o tirada de salvación antes del final de tu siguiente turno. Si no usas este beneficio, en su lugar tienes desventaja en tu siguiente tirada de salvación de Sabiduría (el “peso” persiste).\n\nVentaja en el siguiente ataque o salvación antes del final del siguiente turno; si no se aprovecha, desventaja en la siguiente salvación de Sabiduría.\n\nDuración: Beneficio hasta el final de tu siguiente turno; la contrapartida se resuelve como indica el texto..\n\nAlcance: 15 pies (4,5 m).","showInActions":false},{"id":"whisper-of-finality","kind":"other","name":"Susurro de Finalidad","uses":null,"order":4,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Susurro de Finalidad (desventaja)\n\nCada vez que uses Marca de la Cercanía, realiza una tirada de salvación de Sabiduría CD 12. Si fallas, quedas afectado por un fatalismo latente hasta tu próximo descanso largo:\n\nTienes desventaja en las tiradas de salvación contra la muerte.\n\nNo puedes acercarte voluntariamente a una criatura con todos sus puntos de golpe a menos que superes una prueba de Sabiduría CD 10.\n\nCada uso de la marca exige Sabiduría CD 12. Fallar también impide acercarse voluntariamente a criaturas con todos sus PG salvo prueba de Sabiduría CD 10. La recuperación al amanecer del uso de la marca no elimina esta penalización.\n\nDuración: Si fallas la salvación, hasta tu próximo descanso largo..","showInActions":false}]$text_2665a32b1b3ad0b3$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_a3f66bf2477fa1d5316cd5f74a9c1219';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_76486598066828133b7c1f1235e75f82' and entity_id='inv_ab0a0bc3287dddebffa795628c78acf1' and md5(to_jsonb(t)::text)='7b88f5fb0ed5f67ea2797b1df6614622')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_ab0a0bc3287dddebffa795628c78acf1';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_5615c435e74bef0a$"Objeto · Precio base · Peso\nRaciones (1 día) · 5 pp · 2 lb\n\nRaciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_5615c435e74bef0a$::jsonb,true),'{features}',$text_6268396968fa5288$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_6268396968fa5288$::jsonb,true),'{rules,definition,description}',$text_f8f536bb79fb87b3$[{"id":"official-table","rows":[["Raciones (1 día)","5 pp","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Raciones. Las raciones contienen alim